/* eslint-disable @next/next/no-img-element -- static, already-optimised WebP; next/image would only add JS */

/** Horizontal lockup (CW mark + "CodeWaveTech"), generated by scripts/brand_assets.py. */
const RATIO = 952 / 136;

/**
 * `surface="auto"` follows the theme (navy wordmark on light, light wordmark on
 * dark). `surface="dark"` always uses the light wordmark (e.g. the footer).
 */
export function BrandLogo({
  height = 34,
  surface = "auto",
}: {
  height?: number;
  surface?: "auto" | "dark";
}) {
  const width = Math.round(height * RATIO);
  const alt = "CodeWaveTech home";
  const common = {
    width,
    height,
    loading: "lazy",
    decoding: "async",
  } as const;
  if (surface === "dark") {
    return <img src="/brand/logo-nav-light.webp" alt={alt} {...common} />;
  }
  return (
    <>
      <img className="logo-on-light" src="/brand/logo-nav.webp" alt={alt} {...common} />
      <img className="logo-on-dark" src="/brand/logo-nav-light.webp" alt={alt} {...common} />
    </>
  );
}
